def p(essence, method, pitfall, formula='', memory=''):
    return {'essence':essence,'method':method,'pitfall':pitfall,'formula':formula,'memory':memory}

PACK = {
'材料结构与快速定位':p('资料分析先建立材料地图，再按题干回定位；不是先通读所有数字。',['标题确定主题/时间范围','文字材料只标每段主体；表格先看表头单位；图表先看图例与轴','题干圈主体、时间、单位、问法后再找数'],['累计与当月、人数与人次、全国与局部最容易定位错'],memory='先结构，后题干，再找数。'),
'主体时间单位三锚点':p('任何列式前都做“主体×时间×单位”三重校验。',['主体：谁；时间：哪一期/同比/环比；单位：亿元/万人/%/百分点','若三者任一不一致，宁可重定位也不计算'],['正确公式+错误数据是资料分析最隐蔽的失分方式'],memory='主体、时间、单位，少一个都不算。'),
'统计术语与口径识别':p('先辨清统计口径，再决定公式。',['区分同比/环比、累计/当期、增加/增长、占比/百分点、平均/总量','识别“规模以上、限额以上、实际/名义、可比价”等限定范围'],['把百分点当百分比、把累计同比当当月同比'],memory='先问“它统计的到底是什么”。'),
'现期量与基期量':p('现期B、基期A是一切增长类题目的时间坐标。',['先用题干时间确定谁是B谁是A','再决定直接读数还是通过增长率还原'],['材料最新年份不一定就是题目现期；规划期常有特殊基期'],formula='B=A(1+R)'),
'增长量与增长率':p('增长量是绝对变化，增长率是相对基期的变化。',['先看选项单位：具体单位通常问增长量，%通常问增长率','增长率分母是基期，不是现期'],['“增加X%”与“增加X个百分点”完全不同'],formula='X=B-A=AR；R=X/A'),
'ABRX四量统一模型':p('用A基期、B现期、X增长量、R增长率统一增长类题，减少孤立背公式。',['已知任意两到三量先写B=A+X=A(1+R)','优先根据问法选最短变形，不把四量全算一遍'],['记字母却不确认时间对应会把A/B颠倒'],formula='B=A(1+R), X=AR=B×R/(1+R), A=B/(1+R)'),
'正负增长的方向判断':p('正负增长先做方向自检，可秒排大量错误选项。',['R>0：B>A；R<0：B<A','求基期时正增长答案小于现期，负增长答案大于现期','增长量符号随R变化，但题目有时问“减少量”绝对值'],['负增长仍机械用“现期减增长量”导致符号错']),
'普通增长率':p('普通增长率本质是“变化量/基期量”。',['能直接读A、B时用(B-A)/A','若给现期与增长量，基期=B-X，再算X/(B-X)','比较时先看是否能用倍数/分数结构避免精算'],['把X/B当增长率'],formula='R=(B-A)/A=X/A'),
'增长量速算':p('根据R大小选份数、假设分配或近似BR。',['R接近简单分数→份数法','R较小→假设分配','R极小且选项差大→BR近似AR','比较题先用B和R双大双小判定'],['BR只是小R近似，不是精确式'],formula='X=B×R/(1+R)'),
'基期量速算':p('基期题的提速核心是“方向+选项差距+R结构”。',['先判A相对B方向','R靠近小分→份数辅助；选项宽→截位直除','小R可先估X再B-X'],['同比下降时分母是1-|R|'],formula='A=B/(1+R)'),
'间隔增长率':p('连续两期增长不能简单相加，必须保留乘积项。',['先确认两个增长率覆盖相邻区间','同号增长直接r1+r2+r1r2；一正一负注意乘积为负','只比较时可先用和的大小，必要时再看乘积'],['把两年增速直接相加'],formula='R=r1+r2+r1r2'),
'年均增长率':p('年均增长率是复合增长率，核心是年份间隔n。',['先数间隔，不数数据点','同跨度比较时可直接比较末期/初期，不必开方','求值时用(末/初)^(1/n)-1，选择题可试区间'],['2019到2023是4个增长间隔，不是5'],formula='r=(B/A)^(1/n)-1'),
'年均增长量':p('年均增长量是总变化除以时间间隔。',['确认题目是否按自然年度间隔','末期-初期后除以n','若有五年规划口径先核对基期年份'],['把年份个数当间隔数'],formula='年均增长量=(末期-初期)/n'),
'混合增长率':p('总体增速是基期权重加权平均，必居于各部分增速之间。',['先居中排除','再看基期规模大的部分，总体更靠近它','仍需精算时还原各部分基期做加权'],['不能简单算术平均；权重看基期'],formula='R总=Σ(Ai×Ri)/ΣAi'),
'现期比重':p('现期比重就是同一期“部分/整体”。',['先确认部分与整体同口径同时间','选项差大时优先估算或分数比较','问反推部分/整体时直接变形'],['部分和整体单位要统一'],formula='比重=B部分/B整体'),
'基期比重':p('基期比重可由现期比重乘增速修正项直接得到。',['先算/估现期比重','再乘(1+整体r)/(1+部分r)','先比较两增速判断基期与现期大小关系'],['整体r在分子、部分r在分母，最容易放反'],formula='基期比重=现期比重×(1+r整体)/(1+r部分)'),
'两期比重升降':p('只判断比重升降时不需要算比重，只比增速。',['部分r>整体r→比重上升','部分r<整体r→比重下降','相等→不变'],['比较带符号的增速，不比绝对值']),
'两期比重百分点':p('百分点变化是两个比重的差，增速差只用于方向和粗界。',['先比部分/整体增速判方向','再用比重差公式或还原两期比重','利用比重差通常小于|增速差|做排除'],['绝不能把r部分-r整体直接当百分点答案'],formula='Δ比重=现期比重×(r部分-r整体)/(1+r部分)'),
'比重差与反推':p('比重题可反推部分量、整体量或增速，先把“部分/整体”关系写清。',['已知比重和整体→部分=比重×整体','已知部分和比重→整体=部分/比重','两期比重结合增速关系可反推未知增速方向/范围'],['先统一百分数为小数或分数再运算']),
'现期平均数':p('平均数类统一为“总量/份数”。',['先识别谁是总量、谁是份数','单位通常提示分子分母，如元/人、吨/亩','比较时优先分数比较'],['“每”“均”“单位”常是平均数信号'],formula='平均=B总/B份'),
'基期平均数':p('基期平均数是现期平均乘两个增速修正项。',['确定总量增速b和份数增速a','现期平均×(1+a)/(1+b)','先比较b和a判断基期/现期方向'],['分子分母增速顺序写反'],formula='基期平均=现期平均×(1+a份)/(1+b总)'),
'平均数增长率':p('平均数增速由总量增速与份数增速共同决定。',['先比较b总与a份判升降','求值用(b-a)/(1+a)','小增速时可用b-a做近似上界/附近值'],['b-a不是精确增长率'],formula='r平均=(b总-a份)/(1+a份)'),
'平均数变化量':p('平均数变化量要先得到两期平均或用现期平均×增长率换算。',['先判升降','选项差大时用平均数增长率×基期/现期近似','精确要求高则分别算两期平均再作差'],['变化量有单位，增长率没有单位']),
'现期倍数':p('倍数也是比值问题，先区分“是几倍”和“多几倍”。',['A是B几倍=A/B','A比B多几倍=A/B-1','选项常故意相差1'],['“多X倍”不是“是X倍”'],formula='倍数=A/B；多几倍=A/B-1'),
'基期倍数':p('基期倍数与基期比重/平均的修正结构相同。',['先算现期倍数','乘(1+rB)/(1+rA)','先比较两个增速做方向判断'],['对象A/B的增速不要对调'],formula='基期倍数=现期倍数×(1+rB)/(1+rA)'),
'多几倍与是几倍':p('中文问法是倍数题最大陷阱。',['“A是B的X倍”→A/B=X','“A比B多X倍”→(A-B)/B=X→A/B=X+1','“增长X倍”也要看语境是否指变为原来的X+1倍'],['选项常用差1设计干扰']),
'比值类统一模型':p('比重、平均、倍数本质都是两个量的比值，可统一用“分子增速vs分母增速”判断变化。',['现期比值=N/D','基期比值=现期比值×(1+rD)/(1+rN)','rN>rD→比值上升'],['先确认分子分母的业务含义再套统一式']),
'截位直除':p('截位直除的核心是由选项差距决定精度。',['首位差大→2位有效数常够','相邻选项近→3位或更多','一步除法优先保留分子，只截分母；多步可同时截','结果靠边时提高精度'],['不能背成固定“截三位”']),
'选项差距与计算精度':p('选择题不需要统一精度，计算成本应与选项可分辨程度匹配。',['先看数量级','估相邻选项相对差','选择2位/3位/精算','若方向判断已能排除就停止'],['算得越精不等于越稳，反而可能浪费整卷时间']),
'误差方向判断':p('高级速算必须知道近似使结果偏大还是偏小。',['商：分子大/分母小→偏大','X=B×R/(1+R)随R增大','正增长A=B/(1+R)随R增大而减小','连续近似判断误差是否同向叠加'],['不知道方向就不要主观“修答案”']),
'分数百分数互换':p('把常见百分数转成简单分数能把乘除变成份数口算。',['熟记1/3、1/4、1/5、1/6、1/7、1/8、1/9、1/10、1/11、1/12等','不是为了背表，而是服务增长量、比重和比较'],['近似分数必须结合选项差距与误差方向']),
'份数法':p('R≈a/b时把基期:增长量:现期转为b:a:a+b。',['先百化分','用现期对应a+b份求1份','求A或X','按R估大/估小修正方向'],['负增长要改结构；选项很近回标准公式']),
'假设分配法':p('用易算假设基期分配其增长量，再处理剩余量，把长除法变成几次简单乘减。',['R小且不靠近好分数时优先考虑','先假设A1，算A1×R','从B扣A1及其增长量','对剩余量继续分配'],['选项极近时直除更稳']),
'高位叠加':p('多项加法优先从高位累加，先得到足够区分选项的高位结果。',['同数量级数字按千/百位叠加','低位只有在选项高位相同才继续算'],['精确尾数题不适用']),
'基准值法':p('相近数字求和/平均，用“基准×个数+偏差和”减少重复运算。',['挑接近中间的整百/整千作基准','各数只算偏差','偏差正负抵消后回填'],['基准离数据太远会增加偏差计算']),
'尾数法':p('当正确结果精确且选项尾数可区分时，只算末位/末几位。',['先确认题目要求精确而非约数','看选项从哪一末位开始不同','只保留对应位数运算'],['除法、近似题通常不适用']),
'乘法拆分':p('复杂乘法优先拆成整十百分比、简单分数或邻近整数。',['例如×12%=×(10%+2%)','×37.5%=×3/8','乘以接近1的数可拆为原数±增量'],['拆分要让步骤更少，不要为了技巧而技巧']),
'分数比较':p('比较分数先找同分子/同分母/基准值，再决定是否交叉相乘。',['同分母比分子、同分子比分母','都接近1或某固定比例时比较偏离','数字不大直接交叉相乘'],['分子分母都大不能凭直觉']),
'增长量比较':p('正增长下增长量对现期B和增速R均单调递增。',['双大直接判大，双小直接判小','一大一小时再份数/计算','负增长先统一比较口径'],['只按增速大小排序增长量']),
'增长率比较':p('增长率比较是比较X/A，不一定需要分别精算。',['基期相同看增长量','增长量相同看基期','一般情况用分数比较/交叉相乘','选项问最快增长先排负增长/数量级不符'],['不要用现期量直接替代基期']),
'比重比较':p('多个比重比较就是多个“部分/整体”分数比较。',['同整体直接比部分','整体不同用分数比较','可用交叉相乘或基准比例'],['不能只看部分量大就判比重大']),
'综合判断题策略':p('最后一题的目标是最快找到确定选项，不是把四项都算完。',['先扫四项计算量','读数/方向/数量级优先','复杂多步还原后置','确定答案后停止'],['“正确/错误/能推出/不能推出”方向要先圈']),
'图表趋势题':p('趋势题优先读图，不要把视觉高度直接当数值变化率。',['先看坐标轴是否从0开始','比较增长率要结合基期，不只看折线斜率','柱图看绝对量，折线可能表示率'],['双轴图最容易读错轴']),
'排序计数题':p('问“有几个/多少个年份满足”时，先定判断标准再逐项打勾。',['把阈值写在草稿上','逐年只做必要比较','边界年份精算，其余估算'],['不要每个年份都做完整计算']),
'累计与当月转换':p('累计值与当月值是不同口径，当月常需累计相减。',['当月=本期累计-上期累计','同比当月增长不能直接用两个累计增速相减','若需要去年当月，先还原两期累计再作差'],['这是高频时间口径陷阱']),
'单位换算陷阱':p('单位错误会造成10倍、100倍、10000倍级错误。',['列式前把所有量单位写在数字旁','万/亿、吨/公斤、人/人次、元/万元先统一','比值时同单位可约掉'],['选项数量级可作为最后保险']),
'时间跨度陷阱':p('时间题先数“间隔”而不是数“年份标签”。',['2019→2023有4个间隔','同比默认与上年同期比','五年规划可能以规划前一年作基期'],['材料时间范围不等于题目计算跨度']),
'选项反推法':p('当正算复杂而选项离散时，可用选项倒推验证条件。',['先用数量级/方向排除','代入最有区分度的条件','找到满足所有条件者即停'],['选项信息不足时不要强行反推']),
'资料分析考场止损':p('止损对象是“低收益计算”，不是整个资料模块。',['定位错误反复两次→先跳','多步精算且选项极近→标记后置','综合题先验证低成本项','整卷最后再回'],['具体秒数需靠你的整卷数据校准']),
'资料分析整组时间控制':p('整组速度由阅读、找数、计算三段共同决定。',['先慢做全对建立稳定公式调用','分别记录卡在审题/定位/计算哪一步','同一材料复用定位','综合题控制验证成本'],['恢复期不硬套外部固定时限；整卷后再定个人目标'])
}
